// Guarda cada pedido em teste/saida/ e devolve uma resposta vazia: o teste verifica o pedido, nao a escrita.
const fs = require('fs');
const path = require('path');
const saida = path.join(__dirname, '..', '..', '..', '..', 'saida');
let n = 0;
class Anthropic {
  constructor() {
    this.messages = {
      create: async (params) => {
        n += 1;
        const ferramenta = params.tools[0].name;
        const nome = `${String(n).padStart(2, '0')}-${process.env.CENARIO || 'teste'}-${ferramenta}.txt`;
        fs.writeFileSync(path.join(saida, nome), `=== SYSTEM ===\n${params.system}\n\n=== PEDIDO ===\n${params.messages[0].content}\n`);
        throw new Error('IA falsa: pedido guardado');
      },
    };
  }
}
module.exports = Anthropic;
module.exports.default = Anthropic;
